import{_ as n,o as i,c as a,aj as l}from"./chunks/framework.BdtAaXf2.js";const p="/assets/3.bmiapWYh.gif",e="/assets/4.CPHIZ_1H.gif",g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全03-帧动画/HarmonyOS Next 动画大全03-帧动画.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全03-帧动画/HarmonyOS Next 动画大全03-帧动画.md","lastUpdated":1730788610000,"__rawMarkdown":"## HarmonyOS Next 动画大全03-帧动画\\n\\n## 介绍\\n\\n帧动画`Animator`和属性动画`animation`、显式动画`animateTo`的区别在于帧动画是通过返回应用`onFrame`逐帧回调的方式，让开发者在\\n\\n应用侧的每一帧都可以设置属性值，从而实现设置了该属性值对应组件的动画效果。并且可以轻松的控制动画的播放、暂停等状态。这让它提供了更加强大的动画控制能力\\n\\n## 帧动画示例\\n\\n### 酷狗音乐\\n\\n![3](readme.assets/3.gif)\\n\\n\\n\\n\\n\\n## 基本使用\\n\\n最基本的使用步骤分为4步：\\n\\n1. 引入帧动画\\n2. 创建帧动画\\n3. 监听帧动画的帧变化事件 -> 设置动画\\n4. 开始播放\\n\\n\\n\\n### 1. 引入帧动画\\n\\n```typescript\\nimport { Animator,AnimatorResult } from \'@kit.ArkUI\';\\n```\\n\\n1. `Animator` 是用来创建帧动画对象的\\n2. `AnimatorResult` 表示帧动画对象的类型\\n\\n\\n\\n### 2. 创建帧动画\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  // 2 创建帧动画对象  需要传入动画参数\\n  animator:AnimatorResult=Animator.create({})\\n  build() {\\n\\n  }\\n}\\n```\\n\\n其中，在创建帧动画对象的时候，必须要传入动画参数  `AnimatorOptions`\\n\\n#### 帧动画参数\\n\\n> 以下动画参数绝大部分都和之前讲过的 属性动画和显式动画类似，可以返回前两篇动画文章\\n\\n| 名称         | 类型                                                        | 说明                                                         |\\n| ------------ | ----------------------------------------------------------- | ------------------------------------------------------------ |\\n| `duration`   | `number`                                                    | 动画播放的时长，单位毫秒                                     |\\n| **easing**   | `string`                                                    | 速度曲线                                                     |\\n| `delay`      | `number`                                                    | 延迟时间                                                     |\\n| **fill**     | \\"none\\" \\\\| \\"forwards\\" \\\\| \\"backwards\\" \\\\| \\"both\\"               | 动画播放之外的状态                                           |\\n| `direction`  | \\"normal\\" \\\\| \\"reverse\\" \\\\| \\"alternate\\" \\\\| \\"alternate-reverse\\" | 动画播放方向                                                 |\\n| `iterations` | `number`                                                    | 动画播放次数。设置为0时不播放，设置为-1时无限次播放。**说明:** 设置为除-1外其他负数视为无效取值，无效取值动画默认播放1次。 |\\n| **begin**    | `number`                                                    | 动画插值起点。默认值:0。                                     |\\n| **end**      | `number`                                                    | 动画插值终点。默认值:1。                                     |\\n\\n1. `duration` 动画播放时长，单位毫秒\\n\\n2. **easing** 速度曲线，可以使用以下的值\\n\\n   ```typescript\\n   linear  线性 动画速度保持不变。\\n   ease  缓入缓出 动画开始和结束时速度较低\\n   ease-in 缓入 动画开始时速度较低\\n   ease-out 缓出 动画结束时速度较低\\n   ease-in-out 缓入缓出 动画开始和结束时速度较低\\n   fast-out-slow-in 快出慢入 标准曲线\\n   linear-out-slow-in 线性出慢入 减速曲线\\n   fast-out-linear-in 快出线性入 加速曲线\\n   ```\\n\\n3. `delay` 延迟时间 单位毫秒\\n\\n4. **fill**   动画播放之外的状态\\n\\n   ```\\n   none 正常\\n   forwards 动画执行完毕时，画面停留在最后一帧\\n   backwards 在延迟等待时间呢，画面跳转到第一帧，也就是 begin的值\\n   both 等于同时设置了 forwards 和 backwards\\n   ```\\n\\n5. `direction` 动画播放方向  如当重复执行4次动画时，动画的方向可以设置为   `alternate`\\n\\n   1. A-B\\n   2. B-A\\n   3. A-B\\n   4. B-A\\n\\n6. `iterations` 动画执行次数，-1 为无限\\n\\n7. `begin` 表示动画开始的数值 \\n\\n8. `end` 表示动画结束的数值\\n\\n\\n\\n**示例代码**:\\n\\n```typescript\\n  // 2 创建帧动画对象\\n  animator: AnimatorResult = Animator.create({\\n    //   持续时间\\n    duration: 10000,\\n    //   延迟时间\\n    delay: 0,\\n    //   动画曲线\\n    easing: \\"linear\\",\\n    //   播放次数\\n    iterations: -1,\\n    //   播放模式 播放之外的状态\\n    fill: \\"none\\",\\n    //   播放方向\\n    direction: \\"normal\\",\\n    // 开始角度\\n    begin: 0,\\n    // 结束角度\\n    end: 360\\n  })\\n```\\n\\n### 3. 监听帧变化事件\\n\\n通过给帧动画对象注册 onFrame事件实现监听  begin  ->   end 的数值变化，再将这个数值变化设置给我们的State，便可以实现动画效果了\\n\\n```typescript\\n  @State\\n  angle: number = 0\\n  \\n    // 3 页面开始加载的时候自动触发 aboutToAppear\\n  aboutToAppear() {\\n    //   3 监听帧变化事件\\n    this.animator.onFrame = (value) => {\\n      this.angle = value\\n    }\\n  }\\n```\\n\\n不要忘记了让你的组件使用上这个 变化的状态 angle\\n\\n```typescript\\n  build() {\\n    Column({ space: 40 }) {\\n      Text(\\"变化的动画\\")\\n        .width(100)\\n        .height(100)\\n        .backgroundColor(\\"#0094ff\\")\\n        .rotate({\\n          angle: this.angle\\n        })\\n        \\n      Button(\\"开始动画\\")\\n        .onClick(() => {\\n          // 开始动画\\n\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .padding(20)\\n  }\\n```\\n\\n### 4.  开始动画\\n\\n```typescript\\n  Button(\\"开始动画\\")\\n    .onClick(() => {\\n      this.animator.play()\\n    })\\n```\\n\\n最后，我们查看效果\\n\\n![4](readme.assets/4.gif)\\n\\n\\n\\n\\n\\n## 完整代码\\n\\n```typescript\\n// 1 引入\\nimport { Animator, AnimatorResult } from \'@kit.ArkUI\';\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  angle: number = 0\\n  // 2 创建帧动画对象\\n  animator: AnimatorResult = Animator.create({\\n    //   持续时间\\n    duration: 10000,\\n    //   延迟时间\\n    delay: 0,\\n    //   动画曲线\\n    easing: \\"linear\\",\\n    //   播放次数\\n    iterations: -1,\\n    //   播放模式 播放之外的状态\\n    fill: \\"none\\",\\n    //   播放方向\\n    direction: \\"normal\\",\\n    // 开始角度\\n    begin: 0,\\n    // 结束角度\\n    end: 360\\n  })\\n\\n  // 3 页面开始加载的时候自动触发 aboutToAppear\\n  aboutToAppear() {\\n    //   3 监听帧变化事件\\n    this.animator.onFrame = (value) => {\\n      this.angle = value\\n    }\\n  }\\n\\n  build() {\\n    Column({ space: 40 }) {\\n      Text(\\"变化的动画\\")\\n        .width(100)\\n        .height(100)\\n        .backgroundColor(\\"#0094ff\\")\\n        .rotate({\\n          angle: this.angle\\n        })\\n\\n\\n      Button(\\"开始动画\\")\\n        .onClick(() => {\\n          this.animator.play()\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .padding(20)\\n  }\\n}\\n```\\n\\n\\n\\n## 其他的方法\\n\\n帧对象的其他方法\\n\\n1. `reset` 重置动画器  \\n\\n   ```typescript\\n   reset(AnimatorOptions)\\n   ```\\n\\n2. `play` 播放动画\\n\\n3. `finish` 完成动画播放  相当于设置动画到了 end的数值的状态\\n\\n4. `pause` 暂停动画\\n\\n5. `cancel`  取消动画\\n\\n6. `reverse` 以相反的顺序播放动画\\n\\n## 其他事件\\n\\n1. `onFrame` 帧变化事件\\n2. `onFinish`  动画完成事件\\n3. `onCancel` 动画取消事件\\n4. `onRepeat` 动画重复执行时触发的事件\\n\\n\\n\\n\\n\\n"}'),t={name:"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全03-帧动画/HarmonyOS Next 动画大全03-帧动画.md"};function h(k,s,r,E,d,c){return i(),a("div",null,[...s[0]||(s[0]=[l("",38)])])}const b=n(t,[["render",h]]);export{g as __pageData,b as default};
